package edu.unimagdalena.RCMU.domine.entity;import jakarta.persistence.*;import lombok.*;@Entity@Table(name = "doctors")@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builderpublic class Doctor {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @Column(nullable = false)    private String firstName;    @Column(nullable = false)    private String lastName;    @Column(nullable = false, unique = true)    private String email;    @ManyToOne(fetch = FetchType.LAZY)    @JoinColumn(name = "speciality_id", nullable = false)    private Speciality speciality;}